$sql = 'SELECT id, name, email FROM users WHERE name LIKE :name ORDER BY created_at ' . $order;
$stmt = $this->pdo->prepare($sql);
$stmt->execute([':name' => '%' . $name . '%']);

return $stmt->fetchAll(PDO::FETCH_ASSOC);

$direction = strtoupper($order) === 'DESC' ? 'DESC' : 'ASC';
$pattern = '%' . addcslashes($name, '\\%_') . '%';

$sql = "SELECT id, name, email FROM users WHERE name LIKE :name ESCAPE '\\' ORDER BY created_at {$direction}";
$stmt = $this->pdo->prepare($sql);
$stmt->execute([':name' => $pattern]);

return $stmt->fetchAll(PDO::FETCH_ASSOC);
